export const GetMarketEventsDocument = gql`
    query getMarketEvents($market: ID!, $startEventIndex: Int = 0, $endEventIndex: Int = 100000000, $limit: Int = 10, $delinquencyRecordsFilter: DelinquencyStatusChanged_filter = {id_not: null}, $borrowRecordsFilter: Borrow_filter = {id_not: null}, $depositRecordsFilter: Deposit_filter = {id_not: null}, $feeCollectionRecordsFilter: FeesCollected_filter = {id_not: null}, $repaymentRecordsFilter: DebtRepaid_filter = {id_not: null}, $annualInterestBipsUpdatedRecordsFilter: AnnualInterestBipsUpdated_filter = {id_not: null}, $maxTotalSupplyUpdatedRecordsFilter: MaxTotalSupplyUpdated_filter = {id_not: null}, $withdrawalRequestRecordsFilter: WithdrawalRequest_filter = {id_not: null}, $forceBuyBackRecordsFilter: ForceBuyBack_filter = {id_not: null}, $minimumDepositUpdateRecordsFilter: MinimumDepositUpdated_filter = {id_not: null}, $protocolFeeBipsUpdatedRecordsFilter: ProtocolFeeBipsUpdated_filter = {id_not: null}, $fixedTermUpdatedRecordsFilter: FixedTermUpdated_filter = {id_not: null}, $periodicTermUpdatedRecordsFilter: PeriodicTermUpdated_filter = {id_not: null}, $annualInterestBipsReductionProposalRecordsFilter: AnnualInterestBipsReductionProposed_filter = {id_not: null}) {
  market(id: $market) {
    marketClosedEvent {
      ...MarketClosedData
    }
    periodicTermClosedRecord {
      ...PeriodicTermClosedData
    }
    forceBuyBackDisabledRecord {
      ...DisabledForceBuyBacksData
    }
    delinquencyRecords(
      where: {and: [$delinquencyRecordsFilter, {eventIndex_gte: $startEventIndex, eventIndex_lt: $endEventIndex}]}
      orderBy: eventIndex
      orderDirection: desc
      first: $limit
    ) {
      ...DelinquencyStatusChangedData
    }
    borrowRecords(
      where: {and: [$borrowRecordsFilter, {eventIndex_gte: $startEventIndex, eventIndex_lt: $endEventIndex}]}
      orderBy: eventIndex
      orderDirection: desc
      first: $limit
    ) {
      ...BorrowData
    }
    depositRecords(
      where: {and: [$depositRecordsFilter, {eventIndex_gte: $startEventIndex, eventIndex_lt: $endEventIndex}]}
      orderBy: eventIndex
      orderDirection: desc
      first: $limit
    ) {
      ...DepositData
    }
    feeCollectionRecords(
      where: {and: [$feeCollectionRecordsFilter, {eventIndex_gte: $startEventIndex, eventIndex_lt: $endEventIndex}]}
      orderBy: eventIndex
      orderDirection: desc
      first: $limit
    ) {
      ...FeesCollectedData
    }
    repaymentRecords(
      where: {and: [$repaymentRecordsFilter, {eventIndex_gte: $startEventIndex, eventIndex_lt: $endEventIndex}]}
      orderBy: eventIndex
      orderDirection: desc
      first: $limit
    ) {
      ...RepaymentData
    }
    annualInterestBipsUpdatedRecords(
      where: {and: [$annualInterestBipsUpdatedRecordsFilter, {eventIndex_gte: $startEventIndex, eventIndex_lt: $endEventIndex}]}
      orderBy: eventIndex
      orderDirection: desc
      first: $limit
    ) {
      ...AnnualInterestBipsUpdatedData
    }
    maxTotalSupplyUpdatedRecords(
      where: {and: [$maxTotalSupplyUpdatedRecordsFilter, {eventIndex_gte: $startEventIndex, eventIndex_lt: $endEventIndex}]}
      orderBy: eventIndex
      orderDirection: desc
      first: $limit
    ) {
      ...MaxTotalSupplyUpdatedData
    }
    withdrawalRequestRecords(
      where: {and: [$withdrawalRequestRecordsFilter, {eventIndex_gte: $startEventIndex, eventIndex_lt: $endEventIndex}]}
      orderBy: eventIndex
      orderDirection: desc
      first: $limit
    ) {
      ...WithdrawalRequestProperties
    }
    forceBuyBackRecords(
      where: {and: [$forceBuyBackRecordsFilter, {eventIndex_gte: $startEventIndex, eventIndex_lt: $endEventIndex}]}
      orderBy: eventIndex
      orderDirection: desc
      first: $limit
    ) {
      ...ForceBuyBackData
    }
    minimumDepositUpdateRecords(
      where: {and: [$minimumDepositUpdateRecordsFilter, {eventIndex_gte: $startEventIndex, eventIndex_lt: $endEventIndex}]}
      orderBy: eventIndex
      orderDirection: desc
      first: $limit
    ) {
      ...MinimumDepositUpdatedData
    }
    protocolFeeBipsUpdatedRecords(
      where: {and: [$protocolFeeBipsUpdatedRecordsFilter, {eventIndex_gte: $startEventIndex, eventIndex_lt: $endEventIndex}]}
      orderBy: eventIndex
      orderDirection: desc
      first: $limit
    ) {
      ...ProtocolFeeBipsUpdatedData
    }
    fixedTermUpdatedRecords(
      where: {and: [$fixedTermUpdatedRecordsFilter, {eventIndex_gte: $startEventIndex, eventIndex_lt: $endEventIndex}]}
      orderBy: eventIndex
      orderDirection: desc
      first: $limit
    ) {
      ...FixedTermUpdatedData
    }
    periodicTermUpdatedRecords(
      where: {and: [$periodicTermUpdatedRecordsFilter, {eventIndex_gte: $startEventIndex, eventIndex_lt: $endEventIndex}]}
      orderBy: eventIndex
      orderDirection: desc
      first: $limit
    ) {
      ...PeriodicTermUpdatedData
    }
    annualInterestBipsReductionProposalRecords(
      where: {and: [$annualInterestBipsReductionProposalRecordsFilter, {eventIndex_gte: $startEventIndex, eventIndex_lt: $endEventIndex}]}
      orderBy: eventIndex
      orderDirection: desc
      first: $limit
    ) {
      ...AnnualInterestBipsReductionProposedData
    }
  }
}
    ${MarketClosedDataFragmentDoc}
${PeriodicTermClosedDataFragmentDoc}
${DisabledForceBuyBacksDataFragmentDoc}
${DelinquencyStatusChangedDataFragmentDoc}
${BorrowDataFragmentDoc}
${DepositDataFragmentDoc}
${FeesCollectedDataFragmentDoc}
${RepaymentDataFragmentDoc}
${AnnualInterestBipsUpdatedDataFragmentDoc}
${MaxTotalSupplyUpdatedDataFragmentDoc}
${WithdrawalRequestPropertiesFragmentDoc}
${ForceBuyBackDataFragmentDoc}
${MinimumDepositUpdatedDataFragmentDoc}
${ProtocolFeeBipsUpdatedDataFragmentDoc}
${FixedTermUpdatedDataFragmentDoc}
${PeriodicTermUpdatedDataFragmentDoc}
${AnnualInterestBipsReductionProposedDataFragmentDoc}`;
